#!/bin/bash
# ==============================================================================
# Allwinner A733 SD Card Universal Fix Script (v2.1 - Bootsplash Spinner)
# Supports: Orange Pi 4 Pro, Radxa Cubie A7A, Radxa Cubie A7S
# ==============================================================================
set -euo pipefail

if [ "$(id -u)" -ne 0 ]; then
  echo "[-] Error: Must be run as root"
  exit 1
fi

TARGET="${1:-}"
BOARD="${2:-auto}"

if [ -z "$TARGET" ]; then
  echo "Usage: sudo $0 <sdcard_block_device_or_mountpoint> [opi4pro|cubie-a7a|cubie-a7s]"
  echo "Examples:"
  echo "  sudo $0 /dev/mmcblk0"
  echo "  sudo $0 /dev/sdb cubie-a7a"
  echo "  sudo $0 /media/jonas/opi_root"
  exit 1
fi

CLEANUP_MOUNT=0
MNT=""
RAW_DEV=""

if [ -b "$TARGET" ]; then
  RAW_DEV="$TARGET"
  PART="${TARGET}1"
  [ -b "$PART" ] || PART="${TARGET}p1"
  if [ ! -b "$PART" ]; then
    echo "[-] Could not find partition 1 on $TARGET"
    exit 1
  fi
  if grep -qs "^$PART " /proc/mounts; then
    umount -l "$PART" || true
  fi
  MNT="/mnt/a733_fix_$$"
  mkdir -p "$MNT"
  CLEANUP_MOUNT=1
  echo "[*] Mounting $PART -> $MNT..."
  mount "$PART" "$MNT"
elif [ -d "$TARGET" ]; then
  if [ -d "$TARGET/boot" ]; then
    MNT="$TARGET"
  elif [ -f "$TARGET/uImage" ] || [ -f "$TARGET/vmlinux-6.18.63-sun60iw2" ]; then
    MNT="$(dirname "$TARGET")"
  else
    MNT="$TARGET"
  fi
else
  echo "[-] Target $TARGET is neither a block device nor a directory"
  exit 1
fi

cleanup() {
  if [ "$CLEANUP_MOUNT" -eq 1 ] && [ -n "$MNT" ]; then
    sync || true
    umount -l "$MNT" 2>/dev/null || true
    rmdir "$MNT" 2>/dev/null || true
  fi
  rm -rf "/tmp/a733_fix_payload_$$" 2>/dev/null || true
}
trap cleanup EXIT INT TERM

if [ ! -d "$MNT/boot" ]; then
  echo "[-] Error: Target does not have a /boot directory at $MNT/boot"
  exit 1
fi

if [ "$BOARD" = "auto" ]; then
  if [ -f "$MNT/etc/hostname" ]; then
    HNAME="$(cat "$MNT/etc/hostname" | tr -d ' \n\r')"
    if [[ "$HNAME" == *"cubie-a7a"* ]]; then
      BOARD="cubie-a7a"
    elif [[ "$HNAME" == *"cubie-a7s"* ]]; then
      BOARD="cubie-a7s"
    elif [[ "$HNAME" == *"orangepi"* ]]; then
      BOARD="opi4pro"
    fi
  fi
fi

if [ "$BOARD" = "auto" ]; then
  if [ -f "$MNT/boot/radxaEnv.txt" ]; then
    if grep -q "cubie-a7s" "$MNT/boot/radxaEnv.txt" 2>/dev/null; then
      BOARD="cubie-a7s"
    else
      BOARD="cubie-a7a"
    fi
  else
    BOARD="opi4pro"
  fi
fi

echo "[*] Target board identified as: $BOARD"

TMP_PAYLOAD="/tmp/a733_fix_payload_$$"
mkdir -p "$TMP_PAYLOAD"
echo "[*] Unpacking fix assets..."
sed -n '/^__PAYLOAD_START__$/,$p' "$0" | tail -n +2 | base64 -d | tar -xz -C "$TMP_PAYLOAD"

if [ -n "$RAW_DEV" ]; then
  echo "[*] Flashing verified universal sector 16 bootloader to $RAW_DEV..."
  dd if="$TMP_PAYLOAD/bootloader-orangepi-4-pro.bin" of="$RAW_DEV" bs=512 seek=16 conv=notrunc status=none
fi

KVER="6.18.63-sun60iw2"
for d in "$MNT"/lib/modules/6.*; do
  if [ -d "$d" ]; then
    KVER="$(basename "$d")"
    break
  fi
done
echo "[*] Kernel version in rootfs: $KVER"

if [ "$BOARD" = "opi4pro" ]; then
  DTB_NAME="sun60i-a733-orangepi-4-pro.dtb"
  SPLASH_FILE="$TMP_PAYLOAD/boot.bmp-orangepi"
elif [ "$BOARD" = "cubie-a7s" ]; then
  DTB_NAME="sun60i-a733-cubie-a7s.dtb"
  SPLASH_FILE="$TMP_PAYLOAD/boot.bmp-radxa"
else
  DTB_NAME="sun60i-a733-cubie-a7a.dtb"
  SPLASH_FILE="$TMP_PAYLOAD/boot.bmp-radxa"
fi

echo "[*] Restoring board DTB ($DTB_NAME)..."
mkdir -p "$MNT/boot/dtb/allwinner"
cp -f "$TMP_PAYLOAD/$DTB_NAME" "$MNT/boot/$DTB_NAME"
cp -f "$TMP_PAYLOAD/$DTB_NAME" "$MNT/boot/dtb/allwinner/$DTB_NAME"
cp -f "$TMP_PAYLOAD/sun60i-a733-orangepi-4-pro.dtb" "$MNT/boot/sun60i-a733-orangepi-4-pro.dtb"
cp -f "$TMP_PAYLOAD/sun60i-a733-cubie-a7a.dtb" "$MNT/boot/sun60i-a733-cubie-a7a.dtb"
cp -f "$TMP_PAYLOAD/sun60i-a733-cubie-a7s.dtb" "$MNT/boot/sun60i-a733-cubie-a7s.dtb"

if [ -d "$MNT/boot/dtb-$KVER/allwinner" ]; then
  cp -f "$TMP_PAYLOAD/sun60i-a733-orangepi-4-pro.dtb" "$MNT/boot/dtb-$KVER/allwinner/"
  cp -f "$TMP_PAYLOAD/sun60i-a733-cubie-a7a.dtb" "$MNT/boot/dtb-$KVER/allwinner/"
  cp -f "$TMP_PAYLOAD/sun60i-a733-cubie-a7s.dtb" "$MNT/boot/dtb-$KVER/allwinner/"
fi

echo "[*] Restoring splash screen boot.bmp..."
cp -f "$SPLASH_FILE" "$MNT/boot/boot.bmp"

echo "[*] Restoring verified boot.cmd & boot.scr..."
cp -f "$TMP_PAYLOAD/ref_boot.cmd" "$MNT/boot/boot.cmd"
cp -f "$TMP_PAYLOAD/ref_boot.scr" "$MNT/boot/boot.scr"

echo "[*] Restoring environment files (radxaEnv.txt / orangepiEnv.txt)..."
cat << 'ENV_EOF' > "$MNT/boot/orangepiEnv.txt"
verbosity=7
bootlogo=true
console=both
earlycon=on
overlay_prefix=sun60i-a733
fdtfile=allwinner/DTB_REPLACE
rootdev=/dev/mmcblk0p1
rootfstype=ext4
extraargs=cma=256M
ENV_EOF
sed -i "s/DTB_REPLACE/$DTB_NAME/g" "$MNT/boot/orangepiEnv.txt"
cp -f "$MNT/boot/orangepiEnv.txt" "$MNT/boot/radxaEnv.txt"
cp -f "$MNT/boot/orangepiEnv.txt" "$MNT/boot/a733-allwinnerEnv.txt"

echo "[*] Installing Maxio PHY Ethernet driver module (maxio.ko)..."
PHY_DIR="$MNT/lib/modules/$KVER/kernel/drivers/net/phy"
mkdir -p "$PHY_DIR"
cp -f "$TMP_PAYLOAD/maxio.ko" "$PHY_DIR/maxio.ko"

echo "[*] Installing AIC8800 Wi-Fi modules & firmware..."
WLAN_DIR="$MNT/lib/modules/$KVER/kernel/drivers/net/wireless/aic8800"
mkdir -p "$WLAN_DIR"
for m in aic8800_bsp.ko aic8800_fdrv.ko aic8800_btlpm.ko; do
  [ -f "$TMP_PAYLOAD/$m" ] && cp -f "$TMP_PAYLOAD/$m" "$WLAN_DIR/$m"
done

FW_DST="$MNT/lib/firmware/aic8800"
mkdir -p "$FW_DST"
if [ -d "$TMP_PAYLOAD/aic8800_fw" ]; then
  cp -rf "$TMP_PAYLOAD/aic8800_fw/"* "$FW_DST/"
fi

mkdir -p "$MNT/etc/modules-load.d"
printf "maxio\nmotorcomm\naic8800_bsp\naic8800_fdrv\n" > "$MNT/etc/modules-load.d/a733-drivers.conf"

echo "[*] Installing bootsplash spinning wheel daemon..."
mkdir -p "$MNT/usr/local/bin"
cp -f "$TMP_PAYLOAD/fb_spinner.py" "$MNT/usr/local/bin/a733-bootsplash-spinner"
chmod +x "$MNT/usr/local/bin/a733-bootsplash-spinner"
mkdir -p "$MNT/etc/systemd/system/sysinit.target.wants"
cp -f "$TMP_PAYLOAD/a733-bootsplash-spinner.service" "$MNT/etc/systemd/system/a733-bootsplash-spinner.service"
ln -sf /etc/systemd/system/a733-bootsplash-spinner.service "$MNT/etc/systemd/system/sysinit.target.wants/a733-bootsplash-spinner.service"

echo "[*] Ensuring SSH service and socket are enabled..."
mkdir -p "$MNT/etc/systemd/system/multi-user.target.wants"
mkdir -p "$MNT/etc/systemd/system/sockets.target.wants"
for s in "$MNT/usr/lib/systemd/system/ssh.service" "$MNT/lib/systemd/system/ssh.service"; do
  if [ -f "$s" ]; then
    ln -sf "${s#$MNT}" "$MNT/etc/systemd/system/multi-user.target.wants/ssh.service"
    break
  fi
done
for s in "$MNT/usr/lib/systemd/system/ssh.socket" "$MNT/lib/systemd/system/ssh.socket"; do
  if [ -f "$s" ]; then
    ln -sf "${s#$MNT}" "$MNT/etc/systemd/system/sockets.target.wants/ssh.socket"
    break
  fi
done

echo "[*] Updating systemd service names (orangepi-* -> a733-allwinner-*)..."
SYS_UNITS="$MNT/usr/lib/systemd/system"
[ -d "$SYS_UNITS" ] || SYS_UNITS="$MNT/lib/systemd/system"
if [ -d "$SYS_UNITS" ]; then
  for u in "$SYS_UNITS"/orangepi-*.service; do
    if [ -f "$u" ] && [ ! -L "$u" ]; then
      u_base="$(basename "$u")"
      new_base="${u_base/orangepi-/a733-allwinner-}"
      cp -f "$u" "$SYS_UNITS/$new_base"
      rm -f "$u"
      ln -sf "$new_base" "$u"
    fi
  done
fi

echo "[*] Configuring serial & display autologin..."
LOGIN_USER="orangepi"
if [ "$BOARD" != "opi4pro" ]; then
  LOGIN_USER="radxa"
fi

for unit in serial-getty@ttyS0.service.d getty@tty1.service.d; do
  mkdir -p "$MNT/etc/systemd/system/$unit"
  if [[ "$unit" == *"ttyS0"* ]]; then
    ARGS="-o \"-p -f -- \\u\" --keep-baud --autologin $LOGIN_USER 115200,38400,9600 %I \$TERM"
  else
    ARGS="-o \"-p -f -- \\u\" --noclear --autologin $LOGIN_USER %I \$TERM"
  fi
  cat << AGETTY_EOF > "$MNT/etc/systemd/system/$unit/override.conf"
[Service]
ExecStart=
ExecStart=-/sbin/agetty $ARGS
AGETTY_EOF
done

sync
echo "======================================================================"
echo "[✓] SUCCESS: All fixes applied to SD card!"
echo "    - Board: $BOARD (DTB: $DTB_NAME)"
echo "    - Sector 16 verified bootloader active"
echo "    - Board splash screen installed ($SPLASH_FILE)"
echo "    - Maxio Ethernet PHY driver installed (maxio.ko)"
echo "    - AIC8800 Wi-Fi modules & firmware installed"
echo "    - USB regulators enabled on correct power pins"
echo "    - Systemd units normalized to a733-allwinner-*"
echo "    - Dual console (HDMI tty1 + UART0 ttyS0) + autologin ($LOGIN_USER)"
echo "======================================================================"
exit 0
